<?php
session_start();require_once __DIR__.'/../php/sd_authorization.php';sdRequireRole('technician');
require_once __DIR__.'/../php/conexao.php';require_once __DIR__.'/../php/sd_notifications.php';
if(empty($_SESSION['sd_notice_csrf']))$_SESSION['sd_notice_csrf']=bin2hex(random_bytes(24));
$error='';$rows=[];$history=[];
try{
 if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
  if(!hash_equals($_SESSION['sd_notice_csrf'],(string)($_POST['csrf']??'')))throw new InvalidArgumentException('Token CSRF inválido');
  $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if(!$id || $id<1)throw new InvalidArgumentException('Alerta inválido');
  $actor=mb_substr((string)($_SESSION['username']??$_SESSION['usuario']??$_SESSION['user_id']??'tecnico'),0,130);
  $conexao->begin_transaction();
  try{
   $st=$conexao->prepare('UPDATE sd_notifications SET acknowledged_at=NOW(),acknowledged_by=?,acknowledgments=acknowledgments+1 WHERE id=? AND resolved_at IS NULL AND acknowledged_at IS NULL');$st->bind_param('si',$actor,$id);$st->execute();$changed=$st->affected_rows;$st->close();
   if($changed)sdNotifyHistory($conexao,$id,'acknowledged',$actor);$conexao->commit();
  }catch(Throwable $e){$conexao->rollback();throw $e;}
  header('Location: service-desk-notificacoes.php?ok=1');exit;
 }
 $rows=$conexao->query('SELECT * FROM sd_notifications ORDER BY (resolved_at IS NULL) DESC,(acknowledged_at IS NULL) DESC,last_detected_at DESC LIMIT 250')->fetch_all(MYSQLI_ASSOC);
 $history=$conexao->query('SELECT h.created_at,h.action,h.actor,n.title FROM sd_notification_history h JOIN sd_notifications n ON n.id=h.notification_id ORDER BY h.id DESC LIMIT 50')->fetch_all(MYSQLI_ASSOC);
}catch(Throwable $e){error_log('SD notification UI: '.$e->getMessage());$error='Não foi possível carregar ou confirmar alertas. Verifique a migração e a conexão MySQL.';}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notificações operacionais | CONFINTER</title><link rel="stylesheet" href="../assets/css/sd.css"><link rel="stylesheet" href="../assets/css/confinter-sd-refinement.css"><link rel="stylesheet" href="assets/css/admin-ui.css"><link rel="stylesheet" href="assets/css/confinter-operations-2026.css"><link rel="stylesheet" href="assets/css/confinter-reporting.css"></head><body><?php include __DIR__.'/navbar.php';?><div class="page-wrapper"><main class="sd-wrap sd-admin-surface"><header><a href="service-desk.php">← Service Desk</a><h1>Central de notificações</h1></header><p>Alertas persistentes de SLA e falta de comunicação. A confirmação registra o recebimento, mas não resolve o incidente. A atualização depende do agendador.</p><?php if(isset($_GET['ok'])):?><p role="status">Recebimento confirmado.</p><?php endif;?><?php if($error):?><p role="alert"><?=sdNotifyEsc($error)?></p><?php endif;?><section class="sd-card"><h2>Alertas recentes</h2><div class="sd-table-scroll"><table><thead><tr><th>Alerta</th><th>Severidade</th><th>Detectado</th><th>Estado</th><th>Recebido por</th><th>Ação</th></tr></thead><tbody><?php foreach($rows as $n):?><tr><td><strong><?=sdNotifyEsc($n['title'])?></strong><small><?=sdNotifyEsc($n['detail'])?></small></td><td><?=sdNotifyEsc($n['severity'])?></td><td><?=sdNotifyEsc($n['first_detected_at'])?></td><td><?= $n['resolved_at']?'Resolvido':($n['acknowledged_at']?'Confirmado':'Novo') ?></td><td><?=sdNotifyEsc($n['acknowledged_by']??'—')?></td><td><?php if(!$n['resolved_at']&&!$n['acknowledged_at']):?><form method="post"><input type="hidden" name="csrf" value="<?=sdNotifyEsc($_SESSION['sd_notice_csrf'])?>"><input type="hidden" name="id" value="<?= (int)$n['id']?>"><button type="submit">Confirmar recebimento</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p>Nenhum alerta registrado. Execute o agendador após instalar a migração.</p><?php endif;?></section><section class="sd-card"><h2>Histórico de ações</h2><div class="sd-table-scroll"><table><thead><tr><th>Data</th><th>Ação</th><th>Operador</th><th>Alerta</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=sdNotifyEsc($h['created_at'])?></td><td><?=sdNotifyEsc($h['action'])?></td><td><?=sdNotifyEsc($h['actor'])?></td><td><?=sdNotifyEsc($h['title'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></div><?php include __DIR__.'/footer.php';?></body></html>
